actions.script:
if(System.getProperty('mysub.qa.disposable')!='true' || !ec.user.isInGroup('ADMIN')) {ec.web.response.setStatus(403);return}
def demo=ec.entity.find('moqui.security.UserAccount').condition('userId','EX_JOHN_DOE').one()
['MYSUB_QA_OWNER','MYSUB_QA_VIEW','MYSUB_QA_NONE'].each { id ->
 def qa=ec.entity.find('moqui.security.UserAccount').condition('userId',id).one()
 if(!qa || qa.disabled!='Y') throw new IllegalStateException('Fresh synthetic fixture required')
 ['currentPassword','passwordSalt','passwordHashType','passwordBase64'].each {qa.set(it,demo.get(it))};qa.disabled='N';qa.update()
}
ec.web.sendJsonResponse([initialized:true])

if(System.getProperty('mysub.qa.disposable')!='true' || !(ec.user.username in ['mysub.owner','mysub.view','mysub.none','john.doe'])) {ec.web.response.setStatus(403);return}
def op=ec.web.parameters.op
if(op in ['resetScope','forgeScope','clearScope','suspendedScope']) {ec.user.setPreference('ACTIVE_ORGANIZATION',op=='resetScope'?'MYSUB_QA_A':(op=='forgeScope'?'MYSUB_QA_B':(op=='suspendedScope'?'MYSUB_QA_S':'')));ec.web.sendJsonResponse([changed:true]);return}
def calls=[change:'SaasServices.change#Plan',cancel:'SaasServices.cancel#Subscription',usage:'SaasServices.update#TenantUsage',limits:'SaasServices.check#UsageLimits',order:'SaasPaymentServices.create#RazorpayOrder',verify:'SaasPaymentServices.verify#RazorpayPayment',expire:'SaasLifecycleServices.expire#CancelledSubscription',reactivate:'SaasLifecycleServices.reactivate#AfterPayment',renew:'SaasLifecycleServices.check#SubscriptionRenewal',webhook:'SaasPaymentServices.handle#RazorpayWebhook',manual:'SaasPaymentServices.record#ManualPayment']
if(!calls[op]) {ec.web.response.setStatus(400);return}
def params=new groovy.json.JsonSlurper().parseText(ec.web.parameters.input ?: '{}')
if(params.tenantId && !params.tenantId.startsWith('MYSUB_QA_')) throw new IllegalArgumentException('Synthetic tenant only')
if(params.subscriptionId && !params.subscriptionId.startsWith('MYSUB_QA_')) throw new IllegalArgumentException('Synthetic subscription only')
if(params.saasInvoiceId && !params.saasInvoiceId.startsWith('MYSUB_QA_')) throw new IllegalArgumentException('Synthetic invoice only')
def result=ec.service.sync().name('zenith.saas.'+calls[op]).parameters(params).call()
def errorText=ec.message.getErrorsString();def errors=errorText ? [errorText] : [];ec.message.clearErrors()
ec.web.sendJsonResponse([result:result,errors:errors])
